BASE=Path(__file__).resolve().parents[1]
OUT=BASE/'.cache/batch200/drafts/rewrite_spec';OUT.mkdir(parents=True,exist_ok=True)
P=[['希腊 phaínein／phaínesthai','使显现、显现出来；与光亮有关']]
F=P+[['希腊 phantasía → 拉丁 phantasia','显现的形象；想象'],['古法语 fantaisie → 中古英语 fantasie → fantasy','想象中的画面；幻想']]
PHAS=P+[['希腊 phásis → 新拉丁 phasis','呈现出来的样子'],['英语 phase','相位、月相；变化中的一个阶段']]
EMP=P+[['希腊 en- + phaínein → émphasis','把含义显出来；意味、突出'],['拉丁 emphasis → 英语 emphasis','突出某一点；强调、重视']]
PHEN=P+[['希腊 phainómenon → 后期拉丁 phaenomenon','显现出来的事物'],['英语 phenomenon','可观察或认识到的现象；非凡的人或事']]
SYCO=[['希腊 sûkon；phaínein','无花果；显示：并列材料']]+[['希腊 sûkon + phaínein → sykophántēs','字面为展示无花果者；实际曾指诬告者，命名缘由不确切'],['拉丁 sycophanta；法语 sycophante → 英语 sycophant','告密、诽谤者 → 为私利奉承权势者']]
W=[
E('fantastic','/fænˈtæstɪk/','极好的；奇幻的；难以置信的','好得像超出了日常经验，或者本来就是想象出来的奇异世界。','经法语 fantastique 借入，向前接拉丁 phantasticus、希腊 phantastikós“想象的”。现代能联系 fantasy，但历史上不是英语先给 fantasy 加尾巴才有这个词。',P+[['希腊 phantastikós → 拉丁 phantasticus → 法语 fantastique','想象出来的；奇异的'],['英语 fantastic','幻想的、离奇的 → 非同寻常地好']],'日常说 That’s fantastic! 通常是真心赞叹“太好了”，没有说事情是假的。讲 fantastic creatures 时，才回到奇幻、非现实的画面；fantastic claims 也可能指难以相信的说法。','a fantastic opportunity；a fantastic performance；fantastic creatures。','fantasy 通常是名词；fantastic 常是形容词。unrealistic 专指不符合现实，不能替代称赞用的 fantastic。',('You did a fantastic job explaining a difficult idea.','你把一个难懂的概念解释得非常好。'),('The story is full of fantastic creatures and floating cities.','故事里充满奇异生物和漂浮的城市。'),sources=['https://www.etymonline.com/word/fantastic']),
E('phase','/feɪz/','阶段；月相；相位；分阶段实施','同一件事在变化途中，眼前呈现出的这一副样子。','借新拉丁 phasis，接希腊 phásis“显现、外观”；在英语里发展为阶段、相位等义，动词由名词转用。',PHAS,'月亮的亮面形状有变化，于是有 phases of the Moon；工程从设计到施工也呈现不同阶段。phase in/out 就是分步引入或退出。物理学的 phase 还有专门定义，不能一律译成工作阶段。','the first phase；a phase of development；phase in a new system；phase out old equipment。','stage 和 phase 都能说阶段；phase 常突出变化过程中一种暂时状态。faze 是“使慌乱”，只是同音，来源不同。',('The project has entered its final testing phase.','项目进入了最后的测试阶段。'),('The school will phase in the new timetable over two terms.','学校将用两个学期逐步实行新课表。'),('The chart shows the different phases of the Moon.','图表展示了不同的月相。')),
E('fantasy','/ˈfæntəsi/','幻想；想象中的情景；奇幻作品','现实还没有发生，脑中已经把一整幅画面放映出来。','经古法语 fantaisie、拉丁 phantasia，接希腊 phantasía“形象、想象能力”；词源中的显现也可以发生在心里。',F,'买一座海边小屋的 fantasy 可以只是白日梦；a fantasy novel 则指有魔法、虚构世界等元素的作品类型。这个词不等于谎言：创作想象并不假装自己在陈述事实。','a childhood fantasy；live in a fantasy world；fantasy fiction；a fantasy about something。','imagination 是想象的能力或活动；a fantasy 更像想象出的具体情景，也可指奇幻类型。',('As a child, she had a fantasy of living in a castle.','小时候，她幻想过住在城堡里。'),('The novel blends historical detail with fantasy.','这部小说把历史细节和奇幻想象融在一起。'),sources=['https://www.etymonline.com/word/fantasy']),
E('emphasis','/ˈemfəsɪs/','强调；重点；重视','把某一点从背景里推到前面，让人看见它更重要。','希腊 en-“在其中”与 phaínein“显示”形成 émphasis，经拉丁借入；-sis 在这里是名词形式，不要拆成英语 sis。',EMP,'讲话时加重某个词是 emphasis；学校把重点放在实践上，也是 emphasis。它既可以通过声音表达，也可以通过篇幅、资源分配和排版表达。','put/place emphasis on；with an emphasis on；for emphasis。','stress 可指重音、强调，也可指压力；emphasis 在这里突出“把重点放在哪”，不等于心理紧张。',('The course places more emphasis on practice than on memorisation.','这门课更重视实践，而不是死记硬背。'),('She repeated the final word for emphasis.','她又重复了最后那个词，以加强语气。')),
E('phenomenon','英 /fəˈnɒmɪnən/；美 /fəˈnɑːmənɑːn/，也读 /fəˈnɑːmənən/','现象；引人注目的人或事','某种情况显现出来了，值得观察、描述或解释。','希腊 phainómenon 原是“显现着的东西”的分词名词用法，经后期拉丁 phaenomenon 借入；不是英语 phen 加一个随意词尾。',PHEN,'科学里 a phenomenon 可以很普通，例如水的蒸发；关键是它是要解释的现象。新闻里称某歌手 a phenomenon，则是在说此人引起了非同寻常的关注。复数通常 phenomena。','a natural phenomenon；a social phenomenon；explain a phenomenon；a global phenomenon。','phenomenon 本身不保证神奇；phenomenal 在日常评价中才经常带“惊人的、极好的”意思。',('Condensation is a familiar physical phenomenon.','凝结是一种常见的物理现象。'),('Within a year, the small online game had become a global phenomenon.','不到一年，这款小型网络游戏就成了全球热议的现象级作品。')),
E('phantom','/ˈfæntəm/','幽灵；幻影；虚构的、并不存在的','仿佛看见了一个形体，实际却抓不到相应的实体。','希腊 phántasma 经拉丁 phantasma、古法语 fantosme 和中古英语 fantome 传入；后来拼写恢复 ph-，但读音仍是 /f/。',P+[['希腊 phántasma → 拉丁 phantasma → 古法语 fantosme','显现的形象；幻影'],['中古英语 fantome → 英语 phantom','幽灵；有形象却无对应实体的东西']],'故事中的 phantom 是幽灵；账上的 phantom employee 则是虚构出来领工资的人名。这里强调“像存在却没有对应对象”，不是单纯躲在暗处看不见。','a phantom figure；a phantom employee；phantom footsteps。','ghost 常明确指死者的幽灵；phantom 更容易延伸到虚构记录、幻影等没有实体的东西。',('A pale phantom appeared at the end of the corridor in the film.','电影中，一个苍白的幽灵出现在走廊尽头。'),('The audit uncovered several phantom employees on the payroll.','审计发现工资单上有几名虚构员工。'),sources=['https://www.etymonline.com/word/phantom']),
E('phenomenal','英 /fəˈnɒmɪnəl/；美 /fəˈnɑːmɪnəl/','惊人的；非凡的；现象的','强得、快得或好得让人忍不住把它当成特别的现象来看。','phenomenon 换成 -al 形容词形式，造词受到法语 phénoménal 影响；不是从意思“名声”的 fame 来。',PHEN+[['英语 phenomenon + -al〔受法语形容词影响〕','属于现象的 → 非同寻常、令人惊叹的']],'phenomenal growth 通常说增长幅度惊人，不只是“有增长现象”。哲学中的 phenomenal world 则保留“向经验呈现的世界”这一专门含义，不能译成极好的世界。','phenomenal success；phenomenal growth；a phenomenal memory。','excellent 是很优秀；phenomenal 往往更强，暗示远超一般水平。学术语境中的“现象的”不含称赞。',('Her memory for names is phenomenal.','她记人名的能力惊人。'),('The company experienced phenomenal growth in its first year.','公司在第一年就实现了惊人的增长。')),
E('epiphany','/ɪˈpɪfəni/','顿悟；突然领悟；神的显现〔宗教〕','原来模糊的东西突然亮了起来，你一下子明白了。','希腊 epi-“在……上、向外显现”与 phaínein 形成 epipháneia，经拉丁 epiphania、古法语 epyphanie 和中古英语借入。宗教显现义在先，日常顿悟义后来发展。',P+[['希腊 epipháneia → 拉丁 epiphania → 古法语 epyphanie','显现；神圣的显现'],['中古英语 epiphanie → 英语 epiphany','宗教显现 → 突然明白的时刻']],'have an epiphany 不是逐条记住知识，而是突然看见它们之间的关系。大写 Epiphany 还可指基督教显现节；不要把节日名称读成一次普通灵感。','have an epiphany；a moment of epiphany；the feast of Epiphany。','idea 只是一个想法；epiphany 强调理解突然变得清楚，常带“原来如此”的感受。',('While rereading the letter, she had an epiphany about their misunderstanding.','重读那封信时，她突然明白了两人误会的根源。'),('The final scene brings the character a quiet epiphany.','最后一幕让这个人物在静默中忽然有所领悟。')),
]
W += [
E('emphasise','/ˈemfəsaɪz/','强调；突出〔常见英式拼法〕','把你希望别人记住的那个点，专门亮出来。','emphasis 的动词化形式，使用 -ise 拼法；与 emphasize 同一个词，不是另一套词源。',EMP+[['英语 emphasis → emphasise／emphasize','给某一点更多分量，使之突出']],'可以强调截止日期，也可以用设计突出某个部位。后面通常直接接要强调的内容：emphasise the difference；名词结构才常说 put emphasis on。','emphasise a point；emphasise the importance of；emphasise that…。','emphasise 和 emphasize 的意义、读音相同；英式常见 -ise，英式也用 -ize，美式通常用 -ize。',('The guide emphasised the need to stay on the marked path.','向导强调必须沿着标记好的小路走。'),('The contrasting colours emphasise the shape of the roof.','对比鲜明的颜色突出了屋顶的形状。'),sources=['https://www.etymonline.com/word/emphasize']),
E('fantasize','/ˈfæntəsaɪz/','幻想；想象令人向往的情景','让脑中的小电影继续演，自己先在想象里体验一遍。','fantasy 去掉 -y 后加动词后缀 -ize；英式还常拼 fantasise。',F+[['英语 fantasy + -ize → fantasize','进行幻想、把情景在脑中展开']],'常跟 about doing：fantasize about travelling。通常说令人向往、未必会成真的情景；它本身不包含可实施的步骤，因此不等于已经计划去做。','fantasize about doing；fantasize that…。','plan 要考虑怎样落实；fantasize 可以只停留在想象。imagine 的范围更广，也包括推测普通或不愉快的情形。',('During the long commute, he fantasized about living beside the sea.','漫长的通勤途中，他幻想着住在海边。'),('She sometimes fantasizes that her little bakery has become famous.','她有时幻想自己的小面包店已经出了名。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/fantasize']),
E('tryptophan','英 /ˈtrɪptəfæn/，也读 /ˈtrɪptəʊfæn/；美 /ˈtrɪptəfæn/','色氨酸','一种构成蛋白质的氨基酸；名字留下了早期消化实验中的发现线索。','借德语 Tryptophan：trypto- 接 tryptic／trypsin“胰蛋白酶作用”，-phan 接希腊 phaínein“使显现”。不是 try“尝试”加英语 fan。',P+[['德语 trypto- + -phan → Tryptophan','与胰蛋白酶作用及使显现有关的实验命名'],['英语 tryptophan','色氨酸，一种必需氨基酸']],'名称联系从蛋白质消化产物中识别成分的历史；现代使用时主要指具体分子，不是泛指任何显色物。对人而言属于必需氨基酸，通常要从食物中获得。','dietary tryptophan；a tryptophan residue；tryptophan metabolism。','trypsin 是帮助分解蛋白质的酶；tryptophan 是氨基酸。名字相关，物质类别却不同。',('The table lists the tryptophan content of several foods.','表格列出了几种食物的色氨酸含量。'),('The protein sequence contains two tryptophan residues.','这条蛋白质序列含有两个色氨酸残基。'),sources=['https://www.etymonline.com/word/tryptophan','https://en.wiktionary.org/wiki/tryptophan#English']),
E('phantasm','/ˈfæntæzəm/','幻象；幻影；心中的表象','脑中或眼前似乎有一个影像，却不能把它当成真实在场的物体。','与 phantom 同接希腊 phántasma。经古法语及直接拉丁借入的形式在英语合流，后来拼写向拉丁靠拢；不是给 phantom 加 -asm。',P+[['希腊 phántasma → 拉丁 phantasma；古法语 fantosme','显现的影像、幻象'],['中古英语 fantesme 等 → 英语 phantasm','恢复拉丁式拼写的幻象用词']],'这个词比 phantom 更书面、偏文学或哲学。文学中可说梦里挥之不去的幻影；哲学语境也可指感官或想象留下的心象，不必带有鬼魂含义。','a phantasm of the imagination；a fleeting phantasm；dreams and phantasms。','phantom 常见于幽灵故事，也能修饰虚构对象；phantasm 更像一个被讨论、描写的心中影像。',('The figure dissolved like a phantasm as he woke.','他醒来时，那个人影像幻象一样消散了。'),('The essay asks whether the remembered scene is a fact or a phantasm.','文章追问，记忆中的那一幕是事实，还是一个幻象。'),sources=['https://www.etymonline.com/word/phantasm']),
E('sycophant','/ˈsɪkəfænt/，也读 /ˈsɪkəfənt/','谄媚者；趋炎附势的人','总是顺着有权势的人说好话，因为想从对方那里得到好处。','希腊 sûkon“无花果” + phaínein“展示”形成 sykophántēs，经拉丁和法语路线借入。字面拆分清楚，但为何由“展示无花果”转指诬告者，解释并不确定。',SYCO,'古希腊词曾指诬告、告密者；英语后来发展出依附权势、卑躬奉承的常用义。关于举报无花果走私或侮辱手势的故事，不能当作已经证实的历史链。','a political sycophant；surrounded by sycophants；a court sycophant。','a supporter 可以真诚支持别人；a sycophant 带明显贬义，强调为了讨好而放弃独立判断。',('The director wanted honest advice, not praise from sycophants.','主管想听诚实的建议，不想听谄媚者的吹捧。'),('He called every critic disloyal and rewarded the sycophants around him.','他把所有批评者都说成不忠，却奖赏身边那些奉承他的人。'),sources=['https://www.etymonline.com/word/sycophant']),
E('chloramphenicol','英 /ˌklɔːræmˈfenɪkɒl/；美 /ˌklɔːræmˈfenɪkɔːl/','氯霉素','一种抗生素，长名字把分子结构里的几个线索压缩在了一起。','chlor- + am(ide) + phen- + ni(tro)- + (gly)col；phen- 在这里是苯系化学材料，经过苯旧名 phene 的路线，不是泛泛“看见”。',P+[['法语 phène／英语 phene〔苯旧名〕→ 化学 phen-','苯曾从照明煤气中获得，名称联系光亮'],['近代化学词 chlor- + amide + phen- + nitro- + glycol','把结构提示缩合进药物名称'],['英语 chloramphenicol','氯霉素']],'名字中的 phen- 提示苯系结构，chlor- 提示氯，其余部分也来自化学名称的缩合。先把长词看成几个结构提示的组合，比把每个音节硬译成一句故事更清楚。','chloramphenicol resistance；chloramphenicol eye drops；a chloramphenicol solution。','chloramphenicol 是具体抗生素名；chlorine 是氯元素，phenol 是苯酚，都不能互换。',('The laboratory tested the isolate for resistance to chloramphenicol.','实验室检测了该分离菌株对氯霉素的耐药性。'),('The label identifies chloramphenicol as the active ingredient.','标签注明有效成分为氯霉素。'),sources=['https://www.merriam-webster.com/dictionary/chloramphenicol','https://www.merriam-webster.com/dictionary/phene']),
E('phenology','英 /fəˈnɒlədʒi/；美 /fəˈnɑːlədʒi/','物候学','给自然界做一本日历：什么时候开花、发芽、迁徙、结果。','pheno-“显现” + -logy“研究”；英语术语接十九世纪德语物候研究的命名，不能简单当成 phenomenon 的任意缩写。',P+[['近代科学 pheno- + -logy；德语相关命名','研究周期性生命现象出现的时间'],['英语 phenology','研究物候及其与季节、气候的关系']],'关心的不只是“有没有花”，而是哪一天开、持续多久、是否随年份和环境变化。记录某地每年首次开花日，就是很直观的物候资料。','plant phenology；a phenology project；changes in phenology。','phenology 研究生命事件的时间；phenomenology 是现象学，研究经验等问题。两个词不能只按长短互换。',('The class started a phenology project by recording when the trees opened their buds.','全班通过记录树木何时萌芽，开始了一项物候观察项目。'),('Long records of bird migration are valuable for phenology.','鸟类迁徙的长期记录对物候学很有价值。'),sources=['https://www.etymonline.com/word/phenology','https://www.usanpn.org/about/phenology']),
E('fantasist','/ˈfæntəsɪst/','爱幻想的人；编造经历的人；奇幻创作者','不断创造想象中的情景；这是文学才华还是脱离事实，要看他把想象拿来做什么。','fantasy 换成 -ist 表人的形式；词根的画面仍是在脑中呈现一个世界。',F+[['英语 fantasy + -ist → fantasist','进行幻想、创造幻想的人']],'文学评论里的 fantasist 可以赞赏奇幻作家。日常说 someone is a fantasist 却常带批评：此人夸大或编造自己的经历，让别人以为是真的。','a gifted fantasist；an unreliable fantasist；a writer and fantasist。','a novelist 写小说时不必假装真实；贬义 fantasist 常把想象包装成个人真实经历，语气更重。',('As a fantasist, the novelist can turn an ordinary street into a strange new world.','作为奇幻创作者，这位小说家能把普通街道变成陌生的新世界。'),('His invented stories about meeting world leaders exposed him as a fantasist.','他编造自己会见世界领导人的故事，暴露了他爱胡编经历的本性。'),sources=['https://www.collinsdictionary.com/dictionary/english/fantasist']),
E('diaphanous','/daɪˈæfənəs/','薄而透光的；轻薄透明的','光可以从薄薄的材料中透过去，东西看起来轻得像一层雾。','希腊 dia-“穿过” + phaínein“发亮、显现”形成 diaphanḗs，经中世纪拉丁 diaphanus 借入。现代尾部对应 -ous，但全词不是现代 dia + 英语 phanous。',P+[['希腊 diá + phaínein → diaphanḗs','让光穿透的'],['中世纪拉丁 diaphanus → 英语 diaphanous','薄、轻、透光的']],'常写纱、薄裙、云雾这类轻柔材料。重点是让光穿过且显得轻薄，不要求像无色玻璃一样能看清另一边每个细节。','diaphanous curtains；a diaphanous veil；diaphanous fabric。','transparent 重点是透明；diaphanous 还常带轻薄、纤细的质感，文体更雅。',('Morning light filtered through the diaphanous curtains.','晨光透过轻薄的窗帘洒进来。'),('A diaphanous veil floated above the dancer’s shoulders.','一层轻纱飘在舞者肩头上方。')),
]
W += [
E('photic','英 /ˈfəʊtɪk/；美 /ˈfoʊtɪk/','光的；受光照的','光照得到、光能起作用的地方或现象。','phot- 接希腊 phôs“光”，再加 -ic；phôs 与 phaínein 属更早的光亮同源支线，但 photic 不是英语 phan- 直接换几个字母得来的。',[['希腊 phôs／词干 phōt-','光；与显现词族有更早的同源关系'],['英语 phot- + -ic → photic','与光有关；受光照的']],'海洋的 photic zone 是有光进入的水层。它的位置和范围会受水体透明度等影响，不是整个海洋都有光；其他语境中 photic 也能泛说光刺激。','the photic zone；photic stimulation；photic conditions。','optic 常涉及视觉或眼睛；photic 强调光本身及其作用，不必有眼睛参与。',('The researchers measured light levels throughout the photic zone.','研究人员测量了透光层各处的光照水平。'),('The experiment compared the animals’ responses to different photic conditions.','实验比较了动物对不同光照条件的反应。'),sources=['https://www.etymonline.com/word/photic','https://www.merriam-webster.com/dictionary/photic']),
E('prophase','英 /ˈprəʊfeɪz/；美 /ˈproʊfeɪz/','前期〔细胞分裂阶段〕','细胞分裂的开场阶段：原本松散的遗传物质逐渐收紧成明显的染色体。','近代生物学把 pro-“前、开头”与 phase“阶段”组合成术语；phase 远接希腊 phásis“显现”。',P+[['希腊 phásis → 科学用词 phase','显现出的状态；阶段'],['近代生物学 pro- + phase → prophase','分裂过程开始的前期']],'有丝分裂中，染色体凝缩是前期的醒目标志。减数分裂也用这个词，并区分前期Ⅰ、前期Ⅱ；它们的细节不同，不能只凭同一个词名推定过程完全相同。','during prophase；a cell in prophase；prophase I。','interphase 是分裂间期；prophase 是分裂的前期，pro- 不表示整个分裂开始以前。',('The chromosomes become easier to distinguish during prophase.','前期时，染色体变得更容易辨认。'),('The student labelled this cell as being in prophase.','学生把这个细胞标记为处于前期。'),sources=['https://www.merriam-webster.com/dictionary/prophase']),
E('theophany','英 /θɪˈɒfəni/；美 /θiˈɑːfəni/','神显；神向人显现〔宗教〕','在宗教叙事里，神不再只是被谈论，而是向人显现出来。','希腊 theo-“神” + -phaneia“显现”，形成后期希腊 theopháneia，再经拉丁 theophania 进入英语；不是现代英语 theology 的缩写。',P+[['后期希腊 theo- + -phaneia → theopháneia','神的显现'],['拉丁 theophania → 英语 theophany','神显，宗教叙事与研究用语']],'这个词说明某个宗教叙事或信仰经验中神如何显现，不替阅读者判断事件是否真实发生。可以描述文学中的场景，也可以讨论宗教艺术中的主题。','a biblical theophany；an account of a theophany；a scene of theophany。','epiphany 在日常还可指突然领悟；theophany 明确包含 theo-“神”，一般不会用来称普通生活中的灵光一现。',('The scholar interprets the scene as a theophany.','学者把这一场景解读为神显。'),('The painting presents the theophany through light and cloud.','这幅画通过光与云来表现神的显现。'),sources=['https://www.merriam-webster.com/dictionary/theophany','https://www.collinsdictionary.com/dictionary/english/theophany']),
E('telophase','/ˈteləfeɪz/，也读 /ˈtiːləfeɪz/','末期〔细胞分裂阶段〕','染色体已经分到两边，细胞开始收拾分裂现场、建立新的细胞核。','telo- 接希腊 télos“结束”，后接科学词 phase“阶段”；是近代生物学术语，telo- 不是 telephone 中表示远的 tele-。',P+[['希腊 phásis → 科学用词 phase','状态、阶段'],['近代生物学 telo- + phase → telophase','末期；分裂接近完成的阶段']],'典型有丝分裂末期，两组染色体周围重新形成核结构，纺锤体逐渐解体。把染色体拉向两极主要是前面的后期；不要把末期写成刚开始拉开。减数分裂中也使用末期这一名称。','during telophase；a cell in telophase；telophase II。','anaphase 是染色体分离移向两极的阶段；telophase 是随后收尾。cytokinesis 指细胞质分裂，概念不同，时间可有重叠。',('Two new nuclei become visible as the cell passes through telophase.','细胞经过末期时，两个新的细胞核逐渐可见。'),('The diagram places telophase after anaphase.','图中把末期列在后期之后。'),sources=['https://www.merriam-webster.com/dictionary/telophase']),
E('phenetic','/fəˈnetɪk/','表型相似性的；数值分类学的','先比较“它们整体有多像”，再按相似程度归组。','用 phenotype“表型”的 phen- 材料，仿 genetic 的形式构成 -etic 形容词；不是把 genetic 的意义整体搬过来。',P+[['生物学 phenotype／phen-','表现出的性状'],['近代英语 phen- + -etic〔仿 genetic〕→ phenetic','依据整体性状相似性的']],'phenetic classification 可把很多可测性状放在一起比较。它的划分原则是整体相似程度，不以推断共同祖先为先；看起来像，并不自动等于亲缘最近。','phenetic similarity；phenetic classification；a phenetic analysis。','phylogenetic 关心演化亲缘；phenetic 关心性状的整体相似。phenotypic 泛指表型的，不一定在讨论这种分类方法。',('The phenetic analysis grouped specimens by overall similarity.','表型相似性分析按整体相似程度给标本分组。'),('The team compared the phenetic classification with a classification based on ancestry.','团队把按性状相似性得到的分类与按演化祖先关系得到的分类作了比较。'),sources=['https://www.merriam-webster.com/dictionary/phenetic']),
E('phene','/fiːn/','遗传性状；苯〔旧称〕','生物学里是一项表现出的性状；旧化学文献里，同一拼法还可能在说苯。','生物学用法从 phenotype 中抽取，或直接用希腊 phaínein“显现”的材料；化学旧名另经法语 phène，因苯与照明煤气有关而联系光亮。两路不能串成“苯变成性状”。',P+[['生物学路线：phenotype 的抽取形式或希腊显现材料 → phene','一项受遗传控制的性状'],['并列化学路线：法语 phène → 英语 phene','苯的旧名；命名与照明煤气有关']],'读遗传学文献时，把 a phene 理解为讨论的一项性状，比把它等同于某段 DNA 更合适。读旧化学命名时则要切换到 benzene；没有上下文，不能强行用同一个中文义套全部。','a heritable phene；expression of a phene；phene as an old chemical name。','gene 是遗传材料的单位概念；phene 是性状概念，二者不保证简单一一对应。苯的旧称则是另一条术语线。',('The glossary uses phene for a genetically determined characteristic.','这份术语表用 phene 指受遗传控制的一项特征。'),('The old chemistry text uses phene as a name for benzene.','这本旧化学书用 phene 作为苯的名称。'),sources=['https://www.dictionary.com/browse/phene','https://www.merriam-webster.com/dictionary/phene','https://www.genome.iastate.edu/edu/genetics/glossaries/genetic_terms']),
E('Phanerozoic','英 /ˌfænərəˈzəʊɪk/；美 /ˌfænərəˈzoʊɪk/','显生宙；显生宙的','地层中的生命痕迹变得丰富而容易看见，因此用“显露的生命”来命名这一大段时间。','phanero- 接希腊 phanerós“明显可见的”，-zoic 接生命材料；二十世纪地质学造词，不是古希腊已经有这个地质年代名称。',P+[['希腊 phanerós + 生命材料 -zoic','可见的 + 生命的'],['地质学术语 Phanerozoic〔1930 年提出〕','古生代、中生代、新生代所组成的显生宙']],'这是延续到现在的一大段地质时间，包含熟悉的恐龙时代等。名称突出容易辨认的化石记录，不表示显生宙以前没有生命。作为正式名称，首字母通常大写。','the Phanerozoic eon；Phanerozoic rocks；throughout the Phanerozoic。','eon 是宙，era 是代；Phanerozoic 包含多个 era，不要把它缩成其中某一个代。',('The timeline divides the Phanerozoic into three eras.','时间轴把显生宙分成三个代。'),('The exhibition traces changes in marine life through the Phanerozoic.','展览追踪了显生宙海洋生命的变化。'),sources=['https://www.merriam-webster.com/dictionary/Phanerozoic']),
]
W += [
E('emphasize','/ˈemfəsaɪz/','强调；着重说明；使突出','在一堆信息中给某一点加粗，让别人别漏掉它。','emphasis 动词化为 emphasize，-ize 表示使之具有相应效果；它是英语派生动词，不是直接照搬一个拉丁动词。',EMP+[['英语 emphasis + -ize → emphasize','使重点更加突出；着重说明']],'说 emphasize that… 可以把整句话作为重点。强调既可能靠重复和语气，也可能靠布局；写作中不必为了强调而把每句话都加感叹号。','emphasize the difference；emphasize a word；emphasize that…。','emphasize 常直接接宾语；put emphasis on 则是名词结构。不要机械写成 emphasize on the point。',('The report emphasizes that the figures are estimates.','报告着重说明，这些数字只是估计值。'),('She used a pause to emphasize the next sentence.','她停顿了一下，以突出接下来那句话。'),sources=['https://www.etymonline.com/word/emphasize']),
E('fancy','/ˈfænsi/','想象；一时的喜爱；想要；喜欢；精致花哨的','心里浮出一个想法或喜好，也可以指迎合这种喜好的精致样式。','名词由中古英语 fantasy 一系缩短为 fansy；动词也接相应的幻想、喜爱动词形式。形容词由名词发展，不要把 fancy 拆成 fan“粉丝”加 -cy。',P+[['希腊 phantasía → 拉丁 phantasia → 古法语 fantasie','心里的形象、想象'],['中古英语 fantasy／fansy；相关动词 fancien','缩短形式；想象、喜欢'],['现代英语 fancy','想法、喜爱；想要；讲究或花哨的']],'英式口语 Fancy a coffee? 是“想喝杯咖啡吗”；fancy someone 常是被某人吸引。a fancy restaurant 则是比较讲究的餐馆，不是“幻想出来的餐馆”。','take a fancy to；fancy doing something；a fancy dress；a fancy restaurant。','fancy 可以只是眼下想要；fantasize 更强调展开想象情景。作形容词时 fancy 常说装饰、档次或复杂程度。',('Do you fancy a walk after dinner?','晚饭后想出去走走吗？'),('We chose a simple café rather than a fancy restaurant.','我们选了一家朴素的咖啡馆，没有去讲究的餐厅。'),('The bright little lamp caught her fancy.','那盏鲜亮的小灯让她很喜欢。'),sources=['https://www.etymonline.com/word/fancy','https://en.wiktionary.org/wiki/fancy#English']),
E('fanciful','/ˈfænsɪfəl/','富于想象的；想入非非的；不切实际的','想象的笔画多了，现实依据少了；可以很有趣，也可以不可信。','fancy + -ful；这里 -ful 把“充满想象”变成一种性质。拼写是 fanciful，不是 fancyful。',P+[['希腊 phantasía 经拉丁、法语 → 中古英语 fantasy／fancy','想象；心里的念头'],['英语 fancy + -ful → fanciful','富于想象；偏离现实依据的']],'fanciful illustrations 可以是迷人的奇想插画；a fanciful explanation 则可能是缺乏事实支持的解释。褒贬取决于场合是否需要对现实负责。','a fanciful tale；a fanciful explanation；fanciful creatures。','fancy 常说讲究、花哨；fanciful 更突出想象成分。一个 fancy hotel 可以完全真实，并不 fanciful。',('The book contains fanciful drawings of animals wearing hats.','书中有许多动物戴帽子的奇想插画。'),('The detective rejected the fanciful explanation and asked for evidence.','侦探否定了那个想当然的解释，要求提供证据。')),
E('sycophantic','/ˌsɪkəˈfæntɪk/','谄媚的；阿谀奉承的','说话总往有权者爱听的方向拐，赞美里明显带着讨好的目的。','现代可以联系 sycophant + -ic；历史借入分析接希腊形容词 sykophantikós，不能把英语名词加后缀当成唯一来源。',[['希腊 sýkon；phaínein','无花果；显示：并列材料，具体命名背景有争议']]+[['希腊 sykophántēs → sykophantikós','诬告者及其行为的形容词；后世奉承含义发展'],['英语 sycophantic〔借希腊形容词材料〕','形容谄媚讨好，与 sycophant 对应']],'a sycophantic interview 不只是语气礼貌，而是回避真正问题、不断送上赞美。这个词批评的是缺少独立判断的讨好，不是否定所有称赞。','sycophantic praise；a sycophantic tone；sycophantic behaviour。','polite 是礼貌，可以保留不同意见；sycophantic 常暗示为了取悦对方而一味附和。',('The interviewer’s sycophantic questions avoided every difficult issue.','采访者那些阿谀式提问避开了所有棘手问题。'),('She found the sycophantic praise embarrassing rather than helpful.','她觉得那些谄媚的赞美令人尴尬，谈不上有帮助。'),sources=['https://www.etymonline.com/word/sycophantic']),
E('emphatic','/ɪmˈfætɪk/，也读 /emˈfætɪk/','坚决的；强有力的；明确突出的','把态度摆得很清楚，让人没有空间误以为你只是随口一说。','接希腊 emphatikós 的拉丁化借词形式，与 emphasis 同源。现代可联系 emphasis 的 -tic 形容词形式，但不是 emphasize 的过去分词。',P+[['希腊 emphaínein → emphatikós','显示、表达 → 有表现力的'],['拉丁化形式及英语 emphatic／较早 emphatical','强调的；强烈明确的']],'an emphatic no 是很坚决的拒绝；an emphatic victory 是优势明显的胜利。它不一定靠大喊，也可能是清楚而坚定的措辞或毫无悬念的结果。','an emphatic denial；an emphatic victory；be emphatic about；be emphatic that…。','emotional 强调情绪；emphatic 强调表达或结果鲜明有力。冷静的人也可以作出 emphatic 的回答。',('Her answer was an emphatic no.','她的回答是坚决不行。'),('The team ended the season with an emphatic victory.','球队以一场优势明显的胜利结束了赛季。'),sources=['https://www.etymonline.com/word/emphatic']),
E('emphatically','/ɪmˈfætɪkli/','坚决地；明确有力地；毫无疑问地','把态度说得结结实实，不留下“可能只是试探”的感觉。','现代按 emphatic + -ally 理解；历史上更早的 emphatical 形容词已能形成这个副词，因此不能说它必须等现代短形 emphatic 出现后才造出。',P+[['希腊 emphatikós → 英语 emphatical／emphatic 一系','强烈明确地表达'],['英语 emphatical + -ly；现代对应 emphatic + -ally','emphatically：坚决、明确有力地']],'emphatically deny 是明确坚决地否认；emphatically not 也可把否定加强为“绝对不是”。它说明表达力度，不保证被强调的内容因此就是真的。','deny emphatically；state emphatically；emphatically not。','loudly 是声音大；emphatically 是重点和态度明确。很小声但十分坚定，也可以 emphatically。',('He emphatically denied taking the documents.','他坚决否认拿走了那些文件。'),('This is emphatically not the final version of the plan.','这绝对不是计划的最终版本。'),sources=['https://www.etymonline.com/word/emphatic','https://en.wiktionary.org/wiki/emphatically#English']),
E('fantastically','/fænˈtæstɪkli/','极其；好极了地；奇异地','好到、强到或奇特到，仿佛超出了平常的尺度。','fantastic + -ally；可以承接 fantastic 的称赞、程度或奇幻形态等含义。',P+[['希腊 phantastikós 经拉丁、法语 → 英语 fantastic','想象的、奇异的 → 非常好的'],['英语 fantastic + -ally → fantastically','极其；表现极好地；奇异地']],'fantastically expensive 是贵得惊人，并不是赞美价格；performed fantastically 才是称赞表现极好。跟在后面的词，决定它是在夸质量还是加强程度。','fantastically well；fantastically expensive；fantastically shaped。','fantastically 可以加强负面的 expensive；不能见到它就把整个短语都译成“非常棒”。',('The children performed fantastically despite having little rehearsal time.','虽然排练时间很少，孩子们仍表演得非常出色。'),('The palace was fantastically expensive to maintain.','维护那座宫殿的费用高得惊人。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/fantastically']),
E('fantasise','/ˈfæntəsaɪz/','幻想〔常见英式拼法〕','把还没有发生的愿望，在脑海里先过一遍。','fantasy + -ise；与 fantasize 是同一个动词的拼写变体，-s- 在这里仍读 /z/。',F+[['英语 fantasy + -ise／-ize → fantasise／fantasize','进行幻想；把愿望化成想象情景']],'常见 fantasise about 后接名词或动名词：想象自己在另一座城市生活、拥有另一种职业。英式英语两种拼法都能遇到；一篇文章里保持同一套习惯即可。','fantasise about life abroad；fantasise about doing；fantasise that…。','fantasise 的 -ise 不使意思变得更消极；它与 fantasize 的差异主要在书写习惯。',('They used to fantasise about opening a tiny bookshop together.','他们过去常幻想一起开一家小书店。'),('On rainy days, I fantasise that I am walking through a sunny garden.','下雨时，我会幻想自己正走在阳光明媚的花园里。'),sources=['https://www.oxfordlearnersdictionaries.com/definition/english/fantasize']),
]
