ROOT=[dict(id='C1015',meaning='显现；使看见；与光亮有关',core='某个东西从看不见、没注意，到出现在眼前或心里',image='看见现象是 phenomenon；脑中出现画面是 fantasy；把某点亮出来是 emphasis；薄纱让光穿过是 diaphanous。',intro='希腊 phaínein 的核心是使显现。显现可以发生在眼前，也可以发生在脑中：真实的现象、想象出的世界、突然明白的道理因此走向了不同的词义。它并不保证显现出来的内容是真实可靠的。',forms='phan-、phen-、phas- 等来自相关希腊词形；经过拉丁和法语，某些词写成 f-，如 fantasy。photic 另接 phôs／phot-“光”，是更早同源的旁支，不能当作 phan- 的随意变体。化学 phen- 又通过苯旧名 phene 的命名形成专门意义。',branches=[['幻想与喜好','fantasy、fantastic、fantastically、fantasize、fantasise、fantasist、fancy、fanciful'],['幻影与薄纱透光','phantom、phantasm、diaphanous'],['把意思突出','emphasis、emphasize、emphasise、emphatic、emphatically'],['显现的现象与经验','phenomenon、phenomenal、phenomenology'],['突然领悟及宗教显现','epiphany、theophany'],['阶段与细胞分裂','phase、prophase、telophase'],['生命表现与物候','phenotype、phenotypic、phenetic、phenology、Phanerozoic、phene〔性状义〕'],['奉承的历史支线','sycophant、sycophantic'],['实验命名与化学旁支','tryptophan、phene〔苯旧名〕、chloramphenicol'],['光亮的远源旁支','photic']],contrasts='phenology 是物候学，phenomenology 是现象学。phene 的性状义与苯旧名必须分别理解。sycophant 的无花果拆分不等于其命名故事已确定。fantastic 的日常称赞义不必涉及虚构。',practice='用一个现实中的 phenomenon、一段脑中的 fantasy 和一次 epiphany，各说一句英语。再解释为什么 photic 不应拆成 phan-，为什么 phene 在旧化学书里不能译成遗传性状。',words=list(family),sources=['https://www.etymonline.com/word/fantasy','https://www.etymonline.com/word/sycophant','https://www.etymonline.com/word/photic','https://www.merriam-webster.com/dictionary/phene'])]
